-- Data for BonusType (7 rows)
INSERT INTO public."BonusType" ("id", "code", "name", "description", "parameterSchema", "requiresProductionData", "displayOrder", "isActive", "createdAt", "updatedAt") VALUES ('cmvph5qqw0004n0b0t92ifzfh', 'production_meter', 'Production Meter Bonus', 'Per-meter rate based on drilling type, depth scale, and position. Primary bonus type used across all sites.', '{"type":"object","required":["rateTable","bestRigSelection"],"properties":{"rateTable":{"type":"object","description":"rateTable[drillingType][depthScale][position] = rate per meter"},"bestRigRule":{"type":"object","properties":{"arThresholdMeters":{"type":"number","description":"AR monthly meters gate (e.g. 2500)"}},"description":"MEJOR MAQUINA selection: top AIRE_REVERSO rig wins when its rig monthly total is strictly greater than arThresholdMeters, else top DIAMANTINA rig"},"bestRigSelection":{"enum":["employee_rig_month","best_rig_month","employee_rig"],"type":"string"},"maxMetersPerShift":{"type":"number","description":"Optional cap on meters per shift"}}}', true, 1, true, '"2026-10-26T19:32:18.344Z"', '"2026-11-10T18:04:23.933Z"');
INSERT INTO public."BonusType" ("id", "code", "name", "description", "parameterSchema", "requiresProductionData", "displayOrder", "isActive", "createdAt", "updatedAt") VALUES ('cmvph5qv30005n0b0x9zipiib', 'above_threshold', 'Above Threshold Bonus', 'Bonus for meters exceeding daily threshold per shift (e.g., >22m DDH, >50m RC). Paid at a multiplier of the base rate.', '{"type":"object","required":["thresholds","multiplier","baseRateTable"],"properties":{"multiplier":{"type":"number","description":"Bonus multiplier (e.g., 1.5 for 50% bonus)"},"thresholds":{"type":"object","description":"thresholds[drillingType] = meters threshold"},"baseRateTable":{"type":"object","description":"Same structure as production meter rateTable"}}}', true, 2, true, '"2026-10-26T19:32:18.495Z"', '"2026-11-10T18:04:24.077Z"');
INSERT INTO public."BonusType" ("id", "code", "name", "description", "parameterSchema", "requiresProductionData", "displayOrder", "isActive", "createdAt", "updatedAt") VALUES ('cmvph5qx40006n0b0eel0u8qo', 'monthly_goal', 'Monthly Goal Bonus', 'Flat bonus when rig exceeds monthly production goals. Only driller and helper on that rig receive it.', '{"type":"object","required":["goals","amounts"],"properties":{"goals":{"type":"object","description":"goals[drillingType] = goal meters"},"amounts":{"type":"object","description":"amounts[position] = bonus amount"}}}', true, 3, true, '"2026-10-26T19:32:18.568Z"', '"2026-11-10T18:04:24.148Z"');
INSERT INTO public."BonusType" ("id", "code", "name", "description", "parameterSchema", "requiresProductionData", "displayOrder", "isActive", "createdAt", "updatedAt") VALUES ('cmvph5qz40007n0b08aymhejy', 'high_altitude', 'High Altitude Bonus', 'Flat monthly bonus, pro-rated by days onsite by default; optional full payment when daysWorked >= 1 (e.g., $250,000/month at Coipa).', '{"type":"object","required":["monthlyAmount"],"properties":{"payMode":{"type":"string","description":"prorated (default) or full (daysWorked >= 1 gets full amount)"},"daysInMonth":{"type":"number","description":"Days in month for pro-rating (default 30)"},"monthlyAmount":{"type":"number","description":"Full month bonus amount"}}}', false, 4, true, '"2026-10-26T19:32:18.640Z"', '"2026-11-10T18:04:24.220Z"');
INSERT INTO public."BonusType" ("id", "code", "name", "description", "parameterSchema", "requiresProductionData", "displayOrder", "isActive", "createdAt", "updatedAt") VALUES ('cmvph5r160008n0b0nzo7212q', 'end_of_season', 'End of Season Bonus', 'Base salary multiplier pro-rated by contract days (e.g., 1 salary at Fenix, 3 at ATEX).', '{"type":"object","required":["salaryMultiplier","totalDays","baseSalary"],"properties":{"totalDays":{"type":"number","description":"Total days in the season"},"baseSalary":{"type":"number","description":"Employee base salary (overridable per employee)"},"salaryMultiplier":{"type":"number","description":"Number of salaries to pay"}}}', false, 5, true, '"2026-10-26T19:32:18.714Z"', '"2026-11-10T18:04:24.293Z"');
INSERT INTO public."BonusType" ("id", "code", "name", "description", "parameterSchema", "requiresProductionData", "displayOrder", "isActive", "createdAt", "updatedAt") VALUES ('cmvph5r360009n0b0c9i56sl2', 'directional', 'Directional Drilling Bonus', 'Bonus for directional drilling: hours × factor × rate by depth/diameter.', '{"type":"object","required":["rateTable","hoursFactor"],"properties":{"rateTable":{"type":"object","description":"rateTable[drillingType][depthScale] = rate"},"hoursFactor":{"type":"number","description":"Hours conversion factor (e.g., 22/10.5 = 2.1)"}}}', true, 6, true, '"2026-10-26T19:32:18.786Z"', '"2026-11-10T18:04:24.367Z"');
