-- Table: DailyCrewEntry
DROP TABLE IF EXISTS public."DailyCrewEntry" CASCADE;
CREATE TABLE public."DailyCrewEntry" (
  "id" text NOT NULL,
  "uploadId" text NOT NULL,
  "sheetName" text NOT NULL,
  "date" date NOT NULL,
  "projectName" text,
  "orderNumber" integer,
  "rut" text NOT NULL,
  "rutNormalized" text NOT NULL,
  "fullName" text NOT NULL,
  "cargoRaw" text NOT NULL,
  "cargoNormalized" text NOT NULL,
  "machine" text,
  "diameter" text,
  "escala" text,
  "metros" double precision,
  "horasExtras" double precision,
  "workeraMarkedIn" boolean,
  "workeraMarkedOut" boolean,
  "motivoHorasExtra" text,
  "asistencia" text,
  "asistenciaRaw" text,
  "shiftDayNight" text NOT NULL,
  "turnoAB" text,
  "rawData" jsonb,
  "source" text DEFAULT 'excel'::text NOT NULL,
  "createdAt" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

